import sys
n, a, b, k = map(int, sys.stdin.read().split())
MOD = 10**9 + 7
ways = {x: 0 for x in range(1, n + 1)}
ways[a] = 1
for _ in range(k):
    nxt = {x: 0 for x in range(1, n + 1)}
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            if y != x and abs(x - y) < abs(x - b):
                nxt[y] = (nxt[y] + ways[x]) % MOD
    ways = nxt
print(sum(ways.values()) % MOD)

